// Seeded PRNG (Mulberry32) for deterministic daily rounds and 1v1 challenges
export function createCityPRNG(seed) {
  let s = Math.abs(seed) || 123456789;
  return function() {
    let t = (s += 0x6d2b79f5);
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// Generate a question object with the target city and 3 fair distractor cities
export function getCityQuestion(targetCityOrId, prng = Math.random) {
  const target = typeof targetCityOrId === 'string'
    ? CITY_GRID_DATASET.find(c => c.id === targetCityOrId) || CITY_GRID_DATASET[0]
    : targetCityOrId;

  const otherCities = CITY_GRID_DATASET.filter(c => c.id !== target.id);

  const sameContinent = otherCities.filter(c => c.continent === target.continent);
  const otherContinents = otherCities.filter(c => c.continent !== target.continent);

  const shuffle = (arr) => {
    const copy = [...arr];
    for (let i = copy.length - 1; i > 0; i--) {
      const j = Math.floor(prng() * (i + 1));
      [copy[i], copy[j]] = [copy[j], copy[i]];
    }
    return copy;
  };

  const shuffledSame = shuffle(sameContinent);
  const shuffledOther = shuffle(otherContinents);

  const distractors = [];
  while (distractors.length < 2 && shuffledSame.length > 0) {
    distractors.push(shuffledSame.pop());
  }
  while (distractors.length < 3 && shuffledOther.length > 0) {
    distractors.push(shuffledOther.pop());
  }
  while (distractors.length < 3 && shuffledSame.length > 0) {
    distractors.push(shuffledSame.pop());
  }

  const rawOptions = [target, ...distractors];
  const options = shuffle(rawOptions);

  return {
    target,
    options,
    correctCityId: target.id,
  };
}

// Helper to generate a 5-round game dataset (seeded or random)
export function getRandomQuizRound(seed = null, count = 5) {
  const prng = seed !== null ? createCityPRNG(seed) : Math.random;
  const pool = [...CITY_GRID_DATASET];

  for (let i = pool.length - 1; i > 0; i--) {
    const j = Math.floor(prng() * (i + 1));
    [pool[i], pool[j]] = [pool[j], pool[i]];
  }

  const selectedCities = pool.slice(0, count);
  return selectedCities.map(city => getCityQuestion(city, prng));
}
